package main

import (
	"fmt"
	"runtime"
	"time"
)

func lookup() int {
	ch := make(chan int)
	go func() {
		time.Sleep(10 * time.Millisecond)
		ch <- 42
	}()
	select {
	case v := <-ch:
		return v
	case <-time.After(time.Millisecond):
		return -1
	}
}

func main() {
	for i := 0; i < 100; i++ {
		lookup()
	}
	time.Sleep(100 * time.Millisecond)
	fmt.Println("goroutines:", runtime.NumGoroutine())
}

package main

import (
	"fmt"
	"time"
)

func main() {
	done := make(chan struct{})
	go func() {
		defer func() {
			time.Sleep(20 * time.Millisecond) // flush buffered output
			fmt.Println("worker: flushed")
		}()
		for {
			select {
			case <-done:
				return
			default:
				time.Sleep(5 * time.Millisecond)
			}
		}
	}()
	time.Sleep(30 * time.Millisecond)
	close(done)
	fmt.Println("main: exiting")
}

package main

import (
	"fmt"
	"runtime"
	"time"
)

func lookup() int {
	ch := make(chan int, 1)
	go func() {
		time.Sleep(10 * time.Millisecond)
		ch <- 42 // the answer
		ch <- 0  // a done marker
	}()
	select {
	case v := <-ch:
		return v
	case <-time.After(time.Millisecond):
		return -1
	}
}

func main() {
	for i := 0; i < 100; i++ {
		lookup()
	}
	time.Sleep(100 * time.Millisecond)
	fmt.Println("goroutines:", runtime.NumGoroutine())
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	jobs := make(chan int)
	var wg sync.WaitGroup
	for w := 1; w <= 3; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				fmt.Println("worker", w, "job", j)
			}
		}()
	}
	for j := 1; j <= 5; j++ {
		jobs <- j
	}
	wg.Wait()
}
